/* Purview Gurukul — Specialties: the Dental care track.
   Built from Purview’s "Dental illustrations" guide (internal, October 2026: types of teeth, quadrants,
   tooth numbering, fillings, X-rays, implants, inlays and onlays), extended with what a biller needs to
   work dental claims: CDT codes and the ADA claim form, how dental plans pay, and the common denials.
   Code definitions and plan rules were checked against the ADA claim form instructions, CDT, ICD-10-CM
   and Medicare.gov. The guide’s pictures are not reproduced; the charts here are tables.
   Loaded after spec-vision.js; it adds one track to SPEC_TRACKS and its questions to SPEC_QUIZ. */
"use strict";
(function(){
if(typeof SPEC_TRACKS==="undefined"||typeof SPEC_QUIZ==="undefined") return;

const SRC="Dental illustrations guide (Purview, October 2026, internal), extended and checked against the ADA Dental Claim Form instructions, CDT, ICD-10-CM and Medicare.gov.";

SPEC_TRACKS.push(
{id:"dental",name:"Dental care",short:"Dental",updated:"Dental illustrations guide, October 2026",
 truth:"The guide is the starting point; the client’s playbook and the plan’s manual decide any rule on a claim.",
 blurb:"Dental is the second specialty track: the mouth map a biller needs (teeth, quadrants, surfaces), what the common procedures and X-rays are, the CDT codes and the ADA claim form, how dental plans pay (classes, maximums, frequencies and clauses), and the denials dental billers see most. It is not a clinical course; it stops where the dentist’s work begins.",
 modules:[
{id:"den-a",short:"Dental basics",title:"The mouth map",blurb:"Types of teeth, quadrants and tooth numbers, tooth surfaces, the common procedures and the X-rays, in plain words.",lessons:[
 {id:"den-teeth",title:"Types of teeth, quadrants and tooth numbers",
  keywords:["types of teeth","how many teeth","32 teeth","incisor","canine","cuspid","premolar","bicuspid","molar","wisdom tooth","wisdom teeth","third molar","primary teeth","baby teeth","permanent teeth","dental quadrants","quadrant","upper right quadrant","tooth numbering","tooth numbers","universal numbering","tooth number 1","tooth chart","area of oral cavity","supernumerary","dental basics","dental specialty","teeth numbering"],
  line:"Adults have 32 permanent teeth: 8 incisors, 4 canines, 8 premolars and 12 molars, including the 4 wisdom teeth. The mouth is divided into four quadrants, and every tooth has a number from 1 to 32 (letters A to T for baby teeth). That number goes on the claim, one line per tooth.",
  body:[
   "**Four kinds of teeth.** **Incisors** (8) are the front teeth that cut. **Canines** (4), also called cuspids, are the pointed corner teeth that tear. **Premolars** (8), also called bicuspids, sit behind the canines and crush. **Molars** (12) at the back grind; the last molar in each corner is the **wisdom tooth** (third molar), which often never comes through or comes through crooked. Children have 20 **primary** (baby) teeth, lettered A to T, replaced by the permanent teeth from about age 6.",
   "**Four quadrants.** Looking at the patient, the mouth splits into upper right, upper left, lower left and lower right. Dental work is often described by quadrant: a deep cleaning (scaling and root planing) is billed per quadrant, and the claim form has an **area of oral cavity** code for it: 10 upper right, 20 upper left, 30 lower left, 40 lower right, 01 the whole upper arch, 02 the whole lower arch, 00 the entire mouth.",
   "**Tooth numbers (the Universal system).** Counting starts at the upper right wisdom tooth, number 1, runs along the upper arch to the upper left wisdom tooth, 16, drops to the lower left wisdom tooth, 17, and runs along the lower arch to the lower right wisdom tooth, 32. So 1 to 8 are upper right, 9 to 16 upper left, 17 to 24 lower left, 25 to 32 lower right. The front teeth are 6 to 11 on top and 22 to 27 at the bottom; 8 and 9 are the two big upper front teeth. Baby teeth use letters: A to J across the top (A is the upper right second molar), K to T across the bottom. Extra teeth (supernumerary) are 51 to 82.",
   "**Why it matters for a claim.** The tooth number is a required box on the dental claim, one claim line per tooth: a filling on tooth 30 and a filling on tooth 19 are two lines. The wrong number denies, or worse, pays and creates a duplicate later when the real tooth is treated. The plan also checks the number against history: a crown on a tooth it already paid a crown for five years ago, or an extraction of a tooth it already has as extracted, denies. Other countries use the two-digit FDI system (11 to 48); US claims use Universal numbers."
  ],
  compare:{title:"Universal numbering by quadrant",head:["Quadrant","Permanent teeth","Primary (baby) teeth","Area of oral cavity code"],rows:[["Upper right","1–8 (1 is the wisdom tooth)","A–E","10"],["Upper left","9–16 (16 is the wisdom tooth)","F–J","20"],["Lower left","17–24 (17 is the wisdom tooth)","K–O","30"],["Lower right","25–32 (32 is the wisdom tooth)","P–T","40"]]},
  terms:[["Incisor","A front cutting tooth; eight in all."],["Canine (cuspid)","The pointed corner tooth; four in all."],["Premolar (bicuspid)","The tooth behind the canine; eight in all."],["Molar","A back grinding tooth; twelve in all, including the four wisdom teeth."],["Wisdom tooth (third molar)","The last molar in each quadrant: teeth 1, 16, 17 and 32."],["Primary teeth","The 20 baby teeth, lettered A to T on a claim."],["Supernumerary tooth","An extra tooth, numbered 51 to 82."]],
  tips:["1, 16, 17 and 32 are the wisdom teeth. An impacted-tooth extraction code on tooth 8, a front tooth, is a question for the practice before the claim goes out.","Count by quadrant and you can place any tooth in a second: 1–8 upper right, 9–16 upper left, 17–24 lower left, 25–32 lower right."],
  remember:"32 teeth: 8 incisors, 4 canines, 8 premolars, 12 molars. Numbers 1–32 start at the upper right wisdom tooth and end at the lower right one. One claim line per tooth.",
  source:SRC},
 {id:"den-surfaces",title:"Tooth surfaces: M, O, D, F or B, L and I",
  keywords:["tooth surfaces","tooth surface","mesial","distal","occlusal","incisal","facial surface","buccal","lingual","mod filling","mod","surfaces on a claim","one surface filling","two surface filling","three surface filling","surface codes","how many surfaces","filling by surfaces","d2140","d2150","d2160","d2391","d2392","d2393","d2330"],
  line:"Each tooth has five surfaces, and a filling is coded by how many of them it covers: M mesial (toward the midline), D distal (away from it), O occlusal (the chewing surface of a back tooth), I incisal (the biting edge of a front tooth), F facial or B buccal (the lip or cheek side) and L lingual (the tongue side). ‘MOD’ is a three-surface filling.",
  body:[
   "**The five surfaces.** Picture a tooth as a box. The side facing the front of the mouth (toward the midline between the two front teeth) is **mesial** (M); the side facing the back is **distal** (D). The top of a back tooth, where it chews, is **occlusal** (O); the edge of a front tooth, where it bites, is **incisal** (I). The outer side, toward the lip on front teeth or the cheek on back teeth, is **facial** (F) or **buccal** (B); the inner side, toward the tongue, is **lingual** (L).",
   "**Surfaces set the code.** A filling is coded by material, by position (front or back tooth) and by the **number of surfaces** it covers. One surface on a back tooth: D2140 (amalgam) or D2391 (composite). Two surfaces: D2150 or D2392. Three surfaces: D2160 or D2393. Four or more: D2161 or D2394. Front teeth have their own composite codes, D2330 to D2335. A filling listed as MOD is three surfaces, so a two-surface code with ‘MOD’ in the surface box is a mismatch the plan will question.",
   "**Surfaces on the claim.** The surface letters go in the tooth surface box (item 28 on the ADA form), together with the tooth number, with no spaces: MOD, DO, MOL. Each tooth is its own line. The plan uses the surfaces to check the code, to check history (the same surface of the same tooth filled last month is a duplicate or a replacement) and to apply its rules (a composite on a back tooth may be paid as an amalgam).",
   "**Where surfaces do not apply.** Crowns, root canals, extractions and cleanings are per tooth, per quadrant or per mouth; no surfaces. Only restorations (fillings, inlays, onlays and some repairs) carry surface letters."
  ],
  compare:[{title:"The surfaces",head:["Letter","Surface","Where it is"],rows:[["M","Mesial","The side toward the midline of the mouth"],["D","Distal","The side away from the midline"],["O","Occlusal","The chewing surface of a back tooth"],["I","Incisal","The biting edge of a front tooth"],["F / B","Facial / Buccal","The lip side (front teeth) or cheek side (back teeth)"],["L","Lingual","The tongue side"]]},
   {title:"Filling codes by number of surfaces",head:["Surfaces","Amalgam (any tooth)","Composite, back tooth","Composite, front tooth"],rows:[["1","D2140","D2391","D2330"],["2","D2150","D2392","D2331"],["3","D2160","D2393","D2332"],["4 or more","D2161","D2394","D2335 (4+, or involving the incisal angle)"]]}],
  terms:[["Mesial / distal","Toward the midline / away from the midline."],["Occlusal / incisal","The chewing surface of a back tooth / the biting edge of a front tooth."],["Facial / buccal / lingual","Lip or cheek side / tongue side."],["MOD","A three-surface filling: mesial, occlusal and distal."]],
  tips:["Count the letters, then check the code: MO is two surfaces (D2150 or D2392), MOD is three (D2160 or D2393).","Surfaces only go on restorations. A crown or an extraction with surface letters is a claim-entry error, and some plans reject it."],
  remember:"M, O, D, F or B, L, I. The number of surfaces picks the filling code. No spaces in the box, one tooth per line.",
  source:SRC},
 {id:"den-procedures",title:"Common procedures in plain words: fillings, crowns, inlays, onlays, root canals, extractions, implants",
  keywords:["dental procedures","filling","dental filling","amalgam","composite","tooth coloured filling","silver filling","inlay","onlay","inlay vs onlay","crown","dental crown","root canal","endodontic","extraction","tooth extraction","surgical extraction","impacted","implant","dental implant","bridge","denture","dentures","scaling and root planing","deep cleaning","prophylaxis","cleaning","sealant","fluoride","braces","orthodontics","what is an inlay","what is an onlay","what is an implant"],
  line:"A filling repairs a small cavity; an inlay fills a cavity too big for a filling; an onlay also covers the cusps; a crown covers the whole tooth. A root canal clears the inside of the tooth, an extraction removes it, and an implant is an artificial root placed in the jaw to hold a replacement tooth or bridge. Each is a CDT code family and a plan class.",
  body:[
   "**Fillings.** The decayed part of the tooth is drilled out and replaced with filling material. **Amalgam** is a metal mix of mercury, silver, tin and copper: the silver filling, cheap and long-lasting. **Composite** is tooth-coloured resin. Many plans pay a composite on a back tooth at the amalgam rate (the alternate benefit) and leave the difference to the patient.",
   "**Inlays, onlays and crowns.** When the cavity is too large for a simple filling, the dentist takes an impression and a lab makes a single solid piece that is cemented into the tooth: an **inlay**. An **onlay** is more than an inlay and less than a crown: it also covers one or more cusps (the points) of the tooth. A **crown** caps the whole tooth, after a large break, a root canal or heavy decay. Crowns and onlays are major services on most plans, with replacement limits of five to ten years.",
   "**Root canals and extractions.** A **root canal** (endodontic therapy) removes the infected pulp inside the tooth, cleans the canals and seals them; the tooth usually needs a crown afterwards. Codes differ by tooth: front tooth, premolar or molar. An **extraction** removes the tooth: a simple extraction of an erupted tooth, or a surgical extraction that needs bone removed or the tooth sectioned, including **impacted** wisdom teeth that never came through. Surgical extractions are sometimes medical claims, not dental.",
   "**Replacing teeth.** An **implant** is an artificial root (a titanium post) placed into the jaw; once healed, an abutment and a crown go on it. A **bridge** (fixed partial denture) replaces a missing tooth with a false tooth held by crowns on the neighbours. **Dentures** replace all (complete) or some (partial) of the teeth in an arch and come out. Plans often limit or exclude implants, and the **missing tooth clause** can exclude any replacement of a tooth lost before the policy started.",
   "**Gum care and prevention.** A **prophylaxis** is the routine cleaning, usually twice a year. **Scaling and root planing** is the deep cleaning below the gum line for gum disease, billed per quadrant, followed by **periodontal maintenance** instead of ordinary cleanings. **Sealants** and **fluoride** protect children’s teeth, with age limits on most plans. **Orthodontics** (braces and aligners) is usually a separate benefit with its own lifetime maximum."
  ],
  compare:{title:"Procedure, code family and the usual plan class",head:["Procedure","CDT family","Usual class (typical plan share)"],rows:[["Exam, cleaning, X-rays, fluoride, sealants","D0xxx diagnostic, D1xxx preventive","Preventive (100%)"],["Filling, amalgam or composite","D2140–D2394","Basic (80%)"],["Inlay, onlay, crown","D26xx, D27xx","Major (50%)"],["Root canal","D3310 front tooth, D3320 premolar, D3330 molar","Basic or major, plan by plan"],["Scaling and root planing, perio maintenance","D4341, D4342, D4910","Basic or major, plan by plan"],["Extraction, simple / surgical / impacted","D7140 / D7210 / D7220–D7240","Basic or major; impacted often medical"],["Implant, bridge, dentures","D6010, D6xxx, D5xxx","Major (50%), often limited or excluded"],["Braces","D8xxx","Orthodontic benefit, separate lifetime maximum"]]},
  terms:[["Amalgam","A metal filling (mercury, silver, tin, copper); the silver filling."],["Composite","A tooth-coloured resin filling."],["Inlay / onlay","A lab-made piece cemented into the tooth; an onlay also covers the cusps."],["Crown","A cap that covers the whole tooth."],["Endodontic therapy (root canal)","Removing the infected pulp and sealing the canals."],["Implant","An artificial root placed in the jaw to hold a crown or a bridge."],["Bridge (fixed partial denture)","A false tooth held by crowns on the neighbouring teeth."],["Scaling and root planing","Deep cleaning below the gum line for gum disease, billed per quadrant."]],
  tips:["Filling, inlay, onlay, crown: the same tooth, in order of how much of it the repair covers, and in order of price. The plan’s class (basic or major) and the patient’s share follow that order.","A root canal is often followed by a crown on the same tooth. Two claims, two codes, one tooth: make sure the tooth number matches on both."],
  remember:"Filling → inlay → onlay → crown, from small repair to full cap. Root canal saves the tooth; extraction removes it; implant, bridge or denture replaces it.",
  source:SRC},
 {id:"den-xrays",title:"Dental X-rays: bitewing, periapical, full mouth and panoramic",
  keywords:["dental x-rays","dental xray","x-ray codes dental","bitewing","bitewings","periapical","pa x-ray","fmx","full mouth x-ray","full mouth series","complete series","panoramic","pano","panorex","d0210","d0220","d0230","d0272","d0274","d0330","x-ray frequency","radiographs","radiograph","how often x-rays covered"],
  line:"Four X-rays cover most dental claims: the bitewing (teeth above the gum line and the bone between them, for cavities between teeth), the periapical (one whole tooth from crown to root tip), the full mouth series or FMX (bitewings plus periapicals of every tooth) and the panoramic (the whole mouth on one image). Each has a CDT code and a frequency limit.",
  body:[
   "**Bitewing (D0272 two images, D0274 four).** The most common set. The patient bites on a tab; the image shows the crowns of the upper and lower back teeth and the height of the bone between them. Used to find cavities between teeth, to check the fit of crowns and fillings, and to see wear or breakdown of old fillings. Most plans cover one set a year.",
   "**Periapical (D0220 first image, D0230 each additional).** Shows the whole tooth, from the crown to beyond the root tip where the tooth sits in the jaw, so it catches changes at the root and in the surrounding bone: an abscess, a fracture, the result of a root canal. Taken for one tooth or one area.",
   "**Full mouth series, FMX (D0210).** A set of bitewings and periapicals covering every tooth, used to diagnose gum disease, cavities, abscesses and lesions across the whole mouth. Plans typically allow one every three to five years, and a set of separate bitewings and periapicals that adds up to a full series is paid as an FMX, not as the separate images.",
   "**Panoramic (D0330).** One wide image of the whole mouth, both jaws and the sinuses. It shows the position of erupted and emerging teeth, impacted wisdom teeth, and jaw problems or tumours. Plans usually allow one every three to five years and often count it against the FMX frequency.",
   "**Why it matters for a claim.** X-rays are both a service with a frequency limit and the **attachment** most plans want before they pay for a crown, a root canal, a surgical extraction or scaling and root planing. Taken too soon, the X-ray denies as frequency; missing from a crown claim, the crown waits for a records request. The eligibility check records when the last bitewings and FMX were taken."
  ],
  compare:{title:"X-ray codes and typical frequency",head:["X-ray","CDT","What it shows","Typical plan frequency"],rows:[["Bitewing","D0272 (2 images), D0274 (4)","Crowns of back teeth and the bone between them; cavities between teeth","Once a year"],["Periapical","D0220 first, D0230 each additional","One whole tooth, crown to root tip","As needed, with limits"],["Full mouth series (FMX)","D0210","Every tooth: bitewings plus periapicals","Once in 3 to 5 years"],["Panoramic","D0330","The whole mouth on one image; impacted teeth, jaws","Once in 3 to 5 years, often shared with the FMX"]]},
  terms:[["Bitewing","An X-ray of the crowns of the back teeth and the bone between them."],["Periapical","An X-ray of one whole tooth from crown to root tip."],["Full mouth series (FMX)","Bitewings plus periapicals of every tooth; D0210."],["Panoramic","One image of the whole mouth; D0330."]],
  tips:["Before a crown or root canal claim goes out, check the periapical or bitewing is attached. The plan asks for it either way; attaching it first saves a month.","A full set of bitewings and periapicals billed as separate codes is repriced as an FMX. Bill what was taken, and expect the plan to bundle."],
  remember:"Bitewing = between the teeth, yearly. Periapical = one whole tooth. FMX = every tooth, every 3–5 years. Panoramic = the whole mouth, every 3–5 years.",
  source:SRC}
]},
{id:"den-b",short:"Dental codes",title:"CDT codes and the dental claim",blurb:"The D code families, ICD-10 on dental claims, the ADA claim form boxes that matter, and the attachments and predeterminations plans ask for.",lessons:[
 {id:"den-cdt",title:"CDT codes: the D code families and the ones you will see every day",
  keywords:["cdt","cdt codes","d codes","dental codes","what is cdt","d0120","d0140","d0150","d1110","d1120","d1206","d1208","d1351","d2740","d2750","d2950","d3310","d3330","d4341","d4342","d4910","d5110","d6010","d6058","d7140","d7210","d7240","d8080","d9110","d9230","cdt categories","code on dental procedures","cdt update","icd-10 dental","k02","k04","k05","k08","z01.20","dental diagnosis codes","dental icd"],
  line:"Dental procedures are coded with CDT codes, the Code on Dental Procedures and Nomenclature, owned by the American Dental Association and updated every 1 January. Every code starts with D and a digit that gives its family: D0 diagnostic, D1 preventive, D2 restorative, D3 root canals, D4 gums, D5 dentures, D6 implants and bridges, D7 oral surgery, D8 braces, D9 everything else.",
  body:[
   "**The families.** D0100–D0999 diagnostic (exams and X-rays); D1000–D1999 preventive (cleanings, fluoride, sealants); D2000–D2999 restorative (fillings, inlays, onlays, crowns); D3000–D3999 endodontics (root canals); D4000–D4999 periodontics (gum treatment); D5000–D5899 removable prosthodontics (dentures); D6000–D6199 implant services; D6200–D6999 fixed prosthodontics (bridges); D7000–D7999 oral and maxillofacial surgery (extractions); D8000–D8999 orthodontics; D9000–D9999 adjunctive services (emergency treatment, anaesthesia, consultations).",
   "**Everyday codes.** D0120 periodic exam (established patient), D0150 comprehensive exam, D0140 limited problem-focused exam (the emergency visit); D1110 adult cleaning, D1120 child cleaning, D1206 fluoride varnish, D1351 sealant per tooth; the fillings by surface (previous topics); D2740 porcelain crown, D2750 porcelain fused to metal crown, D2950 core build-up; D3310/D3320/D3330 root canal on a front tooth, premolar, molar; D4341 scaling and root planing, four or more teeth in a quadrant, D4342 one to three teeth, D4910 periodontal maintenance; D5110/D5120 complete upper/lower denture; D6010 implant placement, D6058 the crown on an implant abutment; D7140 simple extraction, D7210 surgical extraction, D7240 fully impacted tooth; D8080 comprehensive braces for an adolescent; D9110 emergency pain relief; D9230 nitrous oxide.",
   "**CDT changes every January.** Codes are added, revised and deleted each year, and the code in force on the date of service is the one the plan accepts. A deleted code on a January claim is an easy denial to prevent.",
   "**CDT or CPT?** Dental plans take CDT codes on the ADA dental claim form (837D electronically). Medical plans take CPT and HCPCS codes with ICD-10 diagnoses on the CMS-1500 (837P). When dental work is billed to a medical plan (an accident, oral surgery, a sleep apnea appliance), it is cross-coded to CPT or HCPCS; CDT codes on a medical claim deny.",
   "**ICD-10 on dental claims.** Many dental plans do not require a diagnosis, but Medicaid programs, medical plans and more commercial plans do, and the ADA form has boxes for it. The dental chapter is K00–K14: K02.- dental caries (decay), K03.81 cracked tooth, K04.- diseases of the pulp and abscesses, K05.- gingivitis and periodontitis, K08.1- loss of teeth, K08.4- partial loss of teeth; Z01.20/Z01.21 is a dental exam without/with abnormal findings; S02.5- is a broken tooth from an injury; M26.6- covers the jaw joint (TMJ) disorders."
  ],
  compare:{title:"CDT families",head:["Range","Family","Examples"],rows:[["D0100–D0999","Diagnostic","D0120, D0140, D0150 exams; D0210, D0272, D0274, D0330 X-rays"],["D1000–D1999","Preventive","D1110, D1120 cleanings; D1206 fluoride; D1351 sealant"],["D2000–D2999","Restorative","D2140–D2394 fillings; D26xx inlays and onlays; D2740, D2750 crowns"],["D3000–D3999","Endodontics","D3310, D3320, D3330 root canals"],["D4000–D4999","Periodontics","D4341, D4342 scaling and root planing; D4910 maintenance"],["D5000–D5899","Removable prosthodontics","D5110, D5120 complete dentures; D5213, D5214 partials"],["D6000–D6999","Implants and fixed bridges","D6010 implant; D6058 implant crown; D6240, D6750 bridge units"],["D7000–D7999","Oral surgery","D7140 simple extraction; D7210 surgical; D7240 impacted"],["D8000–D8999","Orthodontics","D8080 adolescent, D8090 adult comprehensive treatment"],["D9000–D9999","Adjunctive","D9110 palliative; D9230 nitrous oxide; D9310 consultation"]]},
  terms:[["CDT","Code on Dental Procedures and Nomenclature: the ADA’s dental procedure codes, updated every 1 January."],["Cross-coding","Translating a dental service into CPT or HCPCS and ICD-10 so a medical plan can process it."],["K codes","ICD-10-CM chapter K00–K14, diseases of the oral cavity: decay, pulp, gums, loss of teeth."],["837D","The electronic dental claim, the counterpart of the paper ADA form."]],
  tips:["The first digit after the D tells you the family at a glance: D2 is a filling or crown, D4 is gums, D7 is surgery. A D7 code with surface letters, or a D4341 on a single tooth, is wrong on its face.","Check the code set for the date of service after every January: a deleted CDT code denies as invalid."],
  remember:"D0 exams and X-rays, D1 prevention, D2 fillings and crowns, D3 root canals, D4 gums, D5 dentures, D6 implants and bridges, D7 surgery, D8 braces, D9 the rest. CDT for dental plans; CPT and ICD-10 for medical plans.",
  see:[["basics","icd10"],["denial","Procedure code invalid on date of service"]],
  source:SRC},
 {id:"den-claim-form",title:"The ADA Dental Claim Form: tooth, surface, area and the boxes that matter",
  keywords:["ada claim form","ada dental claim form","dental claim form","837d","dental claim boxes","tooth number box","item 27","item 28","item 25","missing teeth chart","missing teeth information","remarks box","item 35","enclosures","item 39","replacement of prosthesis","item 43","item 44","date of prior placement","treatment resulting from accident","item 45","predetermination number","item 2","treating dentist npi","place of treatment dental","dental claim fields"],
  line:"Dental claims go on the ADA Dental Claim Form (837D electronically), not the CMS-1500. Beyond the usual patient, subscriber and provider boxes, it carries the boxes a dental plan lives on: tooth number, surface, area of oral cavity, the missing teeth chart, the replacement date of a prior crown or denture, the accident boxes, enclosures and remarks.",
  body:[
   "**The service lines.** Each line has the procedure date (item 24), the area of oral cavity when the code is per quadrant or arch (25), the tooth system (26, usually JP for Universal numbers), the tooth number or letter (27), the surfaces (28), the CDT code (29), a diagnosis pointer and quantity (29a, 29b), the description (30) and the fee (31). One tooth per line; the same code on three teeth is three lines.",
   "**The boxes plans check first.** Item 1 says whether the claim is for services done or a **request for predetermination**; item 2 carries a predetermination or prior authorization number when there is one. Items 4 to 11 are the other-coverage (COB) boxes. The **missing teeth** chart (item 33 on the current form) marks every tooth the patient has lost, which the plan uses for bridges, partials and the missing tooth clause. Item 34 lists ICD-10 diagnosis codes where required, and item 35, **remarks**, is where the narrative goes.",
   "**The history boxes.** Items 43 and 44 ask whether a crown, bridge or denture is a **replacement** and the date the earlier one was placed: the plan’s replacement limit (five to ten years) is applied from that date, and a blank box is a records request. Items 45 to 47 ask whether the treatment results from an occupational injury, an auto accident or another accident, with the date and state: that routes the claim to a workers’ compensation, auto or medical plan first. Item 39 lists the **enclosures** (radiographs, oral images, models) sent with the claim. Items 40 to 42 cover orthodontics (appliance date, months of treatment).",
   "**Who and where.** The billing dentist or practice (48–52) and the **treating** dentist (53–58) with NPI, license number and specialty code; the place of treatment (38) uses the same place of service codes as medical claims (11 office, 22 outpatient hospital). The treating dentist must be credentialed with the plan for the claim to pay in network.",
   "**Electronic claims.** The 837D carries the same data; attachments go through the plan’s portal or an attachment service with the claim number. The box numbers here follow the current ADA form; older versions number some boxes differently, so check the version the plan or the practice software uses."
  ],
  compare:{title:"Boxes a biller checks before sending",head:["Box (current ADA form)","What goes there","If it is wrong or missing"],rows:[["1 / 2","Actual services or predetermination; the predetermination or prior authorization number","A pre-estimate paid as a claim, or a Medicaid claim denied for no prior authorization"],["4–11","Other dental or medical coverage","CO-22 or a request for the primary EOB"],["25","Area of oral cavity (quadrant or arch) for per-quadrant codes","Scaling and root planing or a quadrant procedure denied"],["27 / 28","Tooth number or letter; surfaces","Wrong tooth denies or creates a later duplicate; surface count must match the code"],["29","CDT code in force on the date of service","Invalid or deleted code"],["33","Missing teeth chart","Bridge or partial held for records; missing tooth clause applied blind"],["34 / 35","Diagnosis codes where required; remarks (narrative)","Medical necessity questioned; narrative request"],["39","Enclosures: X-rays, images, models","Crown, root canal or surgery held for records"],["43 / 44","Replacement of a prosthesis and the prior placement date","Replacement limit applied from the wrong date, or a records request"],["45–47","Accident or occupational injury, date, state","Sent to the wrong payer first"],["53–58","Treating dentist NPI, license, specialty","Provider not credentialed or not matched"]]},
  terms:[["ADA Dental Claim Form","The paper dental claim; 837D is its electronic form."],["Area of oral cavity","The quadrant or arch code (10, 20, 30, 40, 01, 02, 00) for per-quadrant procedures."],["Missing teeth chart","The box on the form that marks every lost tooth."],["Remarks","The narrative box: why the service was needed, dates, anything the plan asked for."],["Predetermination","A claim sent before treatment for the plan’s estimate of what it will pay; item 1 marks it."]],
  tips:["Before a bridge, partial or implant claim, check the missing teeth chart and the prior placement date. Those two boxes decide the missing tooth clause and the replacement limit.","Accident boxes change the payer order: an injury to the teeth goes to the auto, workers’ comp or medical plan before the dental plan."],
  remember:"ADA form, not CMS-1500. Tooth, surface, area, code, fee per line. Missing teeth, replacement date, accident boxes and remarks are where dental claims win or lose.",
  see:[["denial","Information requested from provider"],["denial","Other payer is primary"]],
  source:SRC},
 {id:"den-attachments",title:"Narratives, X-rays and predeterminations: what the plan wants before it pays",
  keywords:["dental narrative","narrative","x-rays required","attachments dental","perio chart","periodontal charting","pocket depths","predetermination","pre-determination","pre-estimate","pre-treatment estimate","prior authorization dental","dental pre-authorization","records request dental","what to attach crown","attach x-ray","supporting documentation dental","national electronic attachment"],
  line:"A dental plan pays major work only when the records show why: a pre-treatment X-ray for a crown or root canal, a periodontal chart with pocket depths for scaling and root planing, the X-ray and a narrative for a surgical extraction, and the prior placement date for any replacement. A predetermination gets the plan’s answer before the work is done; it is an estimate, not a promise.",
  body:[
   "**What to attach, by procedure.** Crown or onlay: a current periapical or bitewing showing the decay or fracture, and a narrative when the reason is a cracked tooth or a failed old restoration. Root canal: the periapical showing the problem at the root, and the post-operative image. Scaling and root planing: the periodontal chart with pocket depths (usually 4 mm or deeper) and bone loss on the X-rays. Surgical or impacted extraction: the X-ray showing the tooth and a narrative of why it was surgical. Bridge, partial, denture or implant: the missing teeth chart, the X-rays and the date of the prior prosthesis. Many plans also want a narrative for any build-up (D2950) and for anything billed as an emergency.",
   "**Narratives.** Short, factual, in the remarks box: the tooth, what was found (fracture, decay to the pulp, 6 mm pockets with bleeding), why the chosen treatment and not a cheaper one, and the date of the previous restoration. The narrative explains what the X-ray shows; it never replaces the X-ray, and it must match the chart. A narrative written to get a claim paid rather than to describe the visit is a compliance problem.",
   "**Predetermination (pre-estimate).** The claim form is sent before treatment with item 1 marked as a request for predetermination; the plan replies with what it expects to pay, the patient’s share and any clause that applies (frequency, missing tooth, alternate benefit, waiting period). Most plans recommend it for crowns, bridges, dentures, implants, periodontal surgery and orthodontics, or for anything over a few hundred dollars. It is not a guarantee: payment depends on eligibility and the maximum left on the date of service.",
   "**Prior authorization.** Medicaid dental programs and some plans require **authorization** before certain services, not just an estimate; without the number on the claim they deny. The eligibility check tells you which the plan needs.",
   "**Records requests.** A claim held for ‘additional information’ is not denied; it is waiting. Send what was asked, the way the plan asks (portal upload, attachment service, fax), with the claim number, and note the date. A records request left unanswered for 30 to 45 days turns into a denial."
  ],
  flow:{steps:["Before the visit: eligibility, frequencies, the maximum left, and whether the plan wants a predetermination or an authorization","Major work: send the predetermination with the X-rays and the narrative; record the plan’s estimate and the patient’s share","After the visit: claim with the right tooth, surfaces, code, prior placement date and enclosures","Attach what the procedure needs: X-ray, perio chart, narrative, missing teeth chart","Records request: send exactly what was asked, with the claim number, and note the date","Denied after the records: appeal with the records and the narrative, inside the plan’s appeal limit"],to:"Paid, or a final denial worked by the client’s rule"},
  terms:[["Periodontal chart","The measurements of the gum pockets around each tooth; the proof for scaling and root planing."],["Pre-treatment X-ray","The image taken before the work that shows why it was needed."],["Predetermination","The plan’s written estimate before treatment; not a guarantee of payment."],["Prior authorization (dental)","Approval required before certain services, mostly on Medicaid programs; the number goes on the claim."]],
  tips:["Attach first, not after the denial: a crown with its X-ray pays in two weeks; a crown without it waits for a records request, then the attachment, then a second review.","Keep the plan’s predetermination letter on the account. When the claim pays less, the letter shows what changed: usually the maximum or the frequency on the date of service."],
  remember:"Crown → X-ray and narrative. Root canal → periapical. Scaling → perio chart. Surgery → X-ray and narrative. Replacement → prior date. Predetermination is an estimate, not a promise.",
  see:[["denial","Information requested from provider"],["denial","Authorization absent or missing"]],
  source:SRC}
]},
{id:"den-c",short:"Dental plans",title:"How dental plans pay",blurb:"Classes and maximums, deductibles and waiting periods, the frequency limits and clauses that shape every dental claim, and when a medical plan pays for dental work.",lessons:[
 {id:"den-plans",title:"Dental plans: classes, the annual maximum, deductibles and waiting periods",
  keywords:["dental insurance","dental plan","how dental insurance works","100 80 50","preventive basic major","dental classes","annual maximum","dental maximum","dental deductible","dental waiting period","dhmo","dental ppo","dental hmo","dental indemnity","does medicare cover dental","medicare dental","medicare advantage dental","medicaid dental","epsdt dental","chip dental","dental benefits","dental coverage"],
  line:"A dental plan sorts services into three classes and pays a different share of each: preventive at about 100%, basic at about 80% and major at about 50%, after a small deductible, up to an annual maximum of typically $1,000 to $2,000. Preventive care starts at once; basic and major services often wait 3 to 12 months after enrolment.",
  body:[
   "**Three classes.** **Preventive** (also called class I or diagnostic and preventive): exams, cleanings, X-rays, fluoride and sealants, usually paid at 100% with no deductible. **Basic** (class II): fillings, simple extractions, often root canals and gum treatment, paid at about 80%. **Major** (class III): crowns, inlays, onlays, bridges, dentures, implants and surgical extractions, paid at about 50%. Where a service sits is the plan’s decision, and it moves: a root canal is basic on one plan and major on the next. **Orthodontics** is usually a fourth class with its own lifetime maximum and age limit.",
   "**The annual maximum.** The most the plan pays per member in a benefit year, typically $1,000 to $2,000; everything above it is the patient’s. One crown can use most of a year’s maximum, and a root canal plus a crown can go past it, so the amount left on the date of service decides how much of a major claim will pay. The maximum resets each benefit year, calendar or plan year. Unlike medical plans, there is no out-of-pocket limit protecting the patient.",
   "**Deductibles and waiting periods.** The dental **deductible** is small (often $25 to $100 a year) and usually waived for preventive care. **Waiting periods** are common on individual plans and some group plans: none for preventive, often 3 to 6 months for basic and 6 to 12 months for major services, sometimes waived when the member had continuous prior coverage. A crown in month four of a plan with a 12-month major waiting period is the patient’s.",
   "**Kinds of plans.** A **dental PPO** has a network with contracted fees; in network the dentist accepts the fee schedule and cannot bill the difference, out of network the plan pays its allowance against the usual and customary fee and the patient can be balance billed. A **DHMO** (dental HMO) assigns a primary dentist, pays the dentist a monthly capitation, has a fixed copay schedule, and sends no claim for many services. **Indemnity** plans pay a percentage of the fee with no network. Discount plans are not insurance at all.",
   "**Government payers and dental.** **Original Medicare** does not cover routine dental care (cleanings, fillings, extractions, dentures, implants); it pays only for dental services tied to a covered medical treatment, such as an exam or treatment needed before a transplant, heart valve surgery or head and neck cancer treatment, and some inpatient hospital dental care. Most **Medicare Advantage** plans add a dental benefit, often through a dental vendor with its own network and maximum. **Medicaid** must cover children’s dental care (EPSDT) and CHIP covers children too; adult Medicaid dental varies by state, from emergency-only to full coverage, often through managed care dental plans."
  ],
  compare:{title:"What a typical dental PPO pays",head:["Class","Examples","Plan share","Deductible","Waiting period (individual plans)"],rows:[["Preventive","Exams, cleanings, X-rays, fluoride, sealants","100%","Usually waived","None"],["Basic","Fillings, simple extractions, often root canals and gum treatment","80%","Yes","3 to 6 months"],["Major","Crowns, inlays, onlays, bridges, dentures, implants, surgical extractions","50%","Yes","6 to 12 months"],["Orthodontics","Braces, aligners","50%, lifetime maximum, often under age 19","Varies","Often 12 months or excluded"]]},
  terms:[["Annual maximum (dental)","The most the plan pays per member in a benefit year, typically $1,000 to $2,000."],["Dental deductible","A small yearly amount the patient pays first, usually waived for preventive care."],["Waiting period (dental)","Months after enrolment before basic or major services are covered."],["Dental PPO","A network plan with contracted fees; no balance billing in network."],["DHMO","A dental HMO: an assigned dentist paid by capitation, a copay schedule, few claims."],["Class (dental)","Preventive, basic or major: the group a service falls in, which sets the plan’s share."]],
  tips:["Before a major claim, three numbers: the plan’s share for that class, the deductible left, and the annual maximum left. Together they are the patient’s estimate.","Medicare does not pay routine dental. A Medicare patient with a dental benefit has it through a Medicare Advantage plan or a separate dental plan: find that card."],
  remember:"Preventive 100, basic 80, major 50, after the deductible, up to the annual maximum. Waiting periods on basic and major. Medicare: no routine dental.",
  see:[["basics","cost-sharing"],["basics","medicare"],["basics","medicaid"]],
  source:SRC},
 {id:"den-rules",title:"Frequency limits, the missing tooth clause, the alternate benefit and other clauses",
  keywords:["frequency limits dental","dental frequency","two cleanings a year","cleaning frequency","crown replacement 5 years","replacement clause","missing tooth clause","alternate benefit","alternate benefit clause","least expensive alternative treatment","leat","amalgam downgrade","downgrade composite","posterior composite downgrade","age limit sealants","age limit fluoride","ortho age limit","cosmetic exclusion","dental clauses","dental plan rules","sealant frequency","srp frequency","perio maintenance frequency"],
  line:"Every dental benefit has a clock (two cleanings a year, bitewings yearly, a crown on the same tooth every five to ten years) and most plans carry three clauses a biller meets daily: the missing tooth clause (no payment to replace a tooth lost before the policy started), the alternate benefit (the plan pays for the cheapest adequate treatment, such as an amalgam rate for a back-tooth composite) and age limits on children’s services and braces.",
  body:[
   "**Frequency limits.** Typical: exams and cleanings twice a benefit year (or once every six months), bitewings once a year, a full mouth series or panoramic once every three to five years, fluoride twice a year for children up to 14 to 19, sealants once per tooth every three years for children up to 14 to 16, scaling and root planing once per quadrant every 24 months, periodontal maintenance two to four times a year, and a crown, bridge or denture on the same tooth or arch replaced only after five to ten years. Inside the window the service denies as frequency, and it is the patient’s only if the practice told them beforehand.",
   "**The missing tooth clause.** If a tooth was extracted or lost before the member’s coverage began, the plan will not pay to replace it: no bridge, partial or implant for that space. Plans check the missing teeth chart, the extraction date and old X-rays. Group plans sometimes waive it; many individual plans do not. The eligibility check asks about it before any replacement work is quoted.",
   "**The alternate benefit (least expensive alternative treatment).** When two treatments would both work, the plan pays the cheaper one and the patient pays the difference: a composite on a back tooth is paid at the amalgam rate, a porcelain crown on a molar at the metal crown rate, an implant at the rate of a partial denture. This is not a denial: the plan pays something and the EOB shows the alternate code. The difference is the patient’s by the plan’s rules, and in-network contracts allow it to be billed.",
   "**Other clauses.** **Age limits**: sealants and fluoride for children, orthodontics usually to age 19. **Cosmetic exclusion**: whitening, veneers and other work done for looks alone is not covered. **Replacement of lost or stolen prostheses**: often excluded. **Pre-existing conditions** beyond the missing tooth clause are rare. **Incentive plans** raise the plan’s share each year the member keeps up preventive visits. The plan booklet and the eligibility response list all of these; the claim is measured against them."
  ],
  compare:{title:"Clauses and what they do to a claim",head:["Rule","What it means","On the claim"],rows:[["Frequency limit","A service is covered so many times per period","Inside the window: denied as frequency, patient responsibility if told"],["Annual maximum","The plan pays up to a yearly cap","Over the cap: paid in part or not at all, the rest to the patient"],["Missing tooth clause","No payment to replace a tooth lost before coverage began","Bridge, partial or implant denied; the patient pays"],["Alternate benefit","The plan pays the cheapest adequate treatment","Paid at the alternate code’s rate; the difference is the patient’s"],["Waiting period","Months before basic or major services are covered","Service inside the wait denied; the patient pays"],["Age limit","Sealants, fluoride, braces covered to a certain age","Denied past the age; the patient pays"],["Cosmetic exclusion","Work for looks alone is not covered","Denied; the patient pays"]]},
  terms:[["Frequency limit (dental)","How often a service is covered: twice a year, once in five years."],["Missing tooth clause","No payment to replace a tooth that was lost before the policy started."],["Alternate benefit (LEAT)","The plan pays for the least expensive alternative treatment; the patient pays the difference."],["Replacement limit","How long a crown, bridge or denture must last before the plan pays for a new one."]],
  tips:["The last-used dates (cleaning, bitewings, FMX) and the prior placement dates (crown, denture) are the facts that decide frequency denials. Record them at eligibility.","A downgrade is not a denial. Post the alternate payment, move the difference to the patient by the plan’s rule, and do not appeal it unless the plan applied the wrong code."],
  remember:"Clocks on every benefit. Missing tooth clause: lost before coverage, not replaced. Alternate benefit: cheapest adequate treatment, difference to the patient. Age limits on children’s services and braces.",
  see:[["denial","CPT reached maximum allowance / frequency"],["denial","Maximum benefit exhausted"],["denial","Pre-existing condition"]],
  source:SRC},
 {id:"den-cob",title:"COB in dental, and when the medical plan pays for dental work",
  keywords:["dental cob","cob dental","two dental plans","dental secondary","dental non duplication","medical plan dental","dental to medical","cross coding","cross-coding","wisdom teeth medical insurance","impacted wisdom teeth medical","accident teeth medical","tmj medical","sleep apnea appliance","e0486","oral surgery medical claim","dental accident","medicare dental exception","which plan pays first dental"],
  line:"Two dental plans coordinate like medical plans: the subscriber’s plan first, the birthday rule for children, and the secondary pays after the primary’s EOB, often under non-duplication. Some dental work is medical: injuries to the teeth, impacted wisdom teeth and other oral surgery, jaw joint (TMJ) treatment, sleep apnea appliances and dental care tied to a medical treatment go to the medical plan first, cross-coded to CPT and ICD-10.",
  body:[
   "**Two dental plans.** The usual order rules apply: the plan that covers the patient as the subscriber pays before the one that covers them as a dependent; for a child, the parent whose birthday comes first in the year; a court decree overrides. The secondary needs the primary’s EOB, and many dental plans pay as secondary by **non-duplication**: they pay only what they would have paid alone minus what the primary paid, which is often nothing. Frequencies and maximums apply on each plan separately.",
   "**Dental work that is medical.** A medical plan pays, before any dental plan, when the care is medical rather than dental: treatment of **injuries** to the teeth and mouth from an accident (often paid in full by the medical plan or an auto policy), **surgical extraction of impacted wisdom teeth** and other oral surgery with a medical reason, **biopsies** and cysts, **TMJ** (jaw joint) treatment, **sleep apnea** oral appliances (HCPCS E0486, prescribed by the physician treating the apnea), cleft and congenital conditions, and dental care needed before a transplant, heart surgery or cancer treatment. These claims are **cross-coded**: CPT or HCPCS and ICD-10 on a CMS-1500, with the records. The dental plan is billed second, with the medical EOB, for whatever its own rules cover.",
   "**Medicare and dental.** Original Medicare pays none of the routine dental work, so a Medicare patient’s cleanings and crowns go to their Medicare Advantage dental benefit or a stand-alone dental plan. Medicare does pay for dental services inextricably linked to a covered medical service (the exam and treatment before a transplant or heart valve surgery, treatment around head and neck cancer therapy) and for some inpatient hospital dental care: those are medical claims to Medicare.",
   "**Accident boxes.** The ADA form’s accident items (45 to 47) tell the dental plan an injury is involved; the dental plan then expects the auto, workers’ compensation or medical plan to have been billed first. A broken front tooth from a fall at work is a workers’ compensation claim before it is a dental claim.",
   "**The denial you will see.** ‘Other coverage may be primary’ or CO-22 on a dental claim: another dental plan is on file, or the service looks medical or accident-related. Check the other-coverage boxes, the accident boxes and the order, then bill the right plan first and send the EOB to the second."
  ],
  compare:{title:"Who pays first",head:["Situation","First","Then"],rows:[["Two dental plans, adult","The plan where the patient is the subscriber","The other plan, with the EOB; often non-duplication"],["Two dental plans, child","The parent whose birthday comes first in the year (birthday rule)","The other parent’s plan, with the EOB"],["Broken tooth from a car accident","The auto policy (no-fault or liability), then the medical plan","The dental plan, with the EOB"],["Impacted wisdom teeth, medical necessity documented","The medical plan (cross-coded)","The dental plan, with the medical EOB"],["Sleep apnea appliance","The medical plan (E0486, with the sleep study)","Usually nothing: dental plans do not cover it"],["Routine cleaning, Medicare patient","The Medicare Advantage dental benefit or the stand-alone dental plan","The patient; Medicare pays nothing"],["Dental clearance before a transplant, Medicare","Medicare (medical claim)","The secondary medical plan"]]},
  terms:[["Non-duplication (dental)","The secondary pays what it would have paid alone minus the primary’s payment, often nothing."],["Cross-coding","Billing dental work to a medical plan with CPT or HCPCS and ICD-10 on a CMS-1500."],["E0486","The HCPCS code for a custom oral appliance for sleep apnea, a medical claim."],["Inextricably linked (Medicare)","Dental care Medicare pays for because a covered medical treatment depends on it."]],
  tips:["Before billing wisdom teeth or oral surgery to the dental plan, ask whether the medical plan should see it first: impaction with a medical reason, infection, a cyst. Medical first can save the patient the whole dental maximum.","Never bill both plans at once ‘to see which pays’. Primary first, then the secondary with the EOB; two payments is a refund."],
  remember:"Two dental plans: subscriber first, birthday rule for children, EOB to the second. Injury, oral surgery, TMJ, sleep appliance, medically linked dental care: medical plan first, cross-coded.",
  see:[["basics","cob"],["denial","Other payer is primary"],["denial","Primary EOB required"]],
  source:SRC}
]},
{id:"den-d",short:"Dental denials",title:"Working dental claims and denials",blurb:"The ten denials dental billers see most and the first check for each, what the patient owes after the EOB, and what makes a dental claim stand up on review.",lessons:[
 {id:"den-denials",title:"The common dental denials and the first thing to check",
  keywords:["dental denials","common dental denials","dental claim denied","why was the dental claim denied","why was the crown denied","frequency denial dental","annual maximum reached","maximum reached dental","missing tooth clause denial","not a covered benefit dental","waiting period denial","x-rays required denial","records request dental","narrative required","tooth number error","duplicate dental claim","timely filing dental","predetermination missing","prior authorization dental denied","dentist not in network","what to do when a dental claim is denied"],
  line:"Most dental denials are one of ten: frequency limit, annual maximum reached, missing tooth clause, alternate benefit (a lower payment, not a denial), not a covered benefit or cosmetic, waiting period, records or narrative needed, tooth, surface or quadrant error (including duplicates), timely filing, and no prior authorization or an out-of-network dentist. Each has one first check, and most are prevented at eligibility.",
  compare:{title:"The ten denials",head:["Denial","What it means","First check","Usual fix"],rows:[
   ["Frequency limit","The service was done inside the plan’s window","The last-used date for that service on the eligibility response","Patient responsibility if told; otherwise the practice’s rule; no appeal unless the date is wrong"],
   ["Annual maximum reached","The plan has paid its yearly cap","The maximum left on the date of service; the benefit year","Patient responsibility; split large treatment across benefit years next time"],
   ["Missing tooth clause","The replaced tooth was lost before coverage began","Extraction date against the policy effective date; the missing teeth chart","Patient responsibility, or appeal if the tooth was lost after the effective date"],
   ["Alternate benefit","Paid at the cheaper treatment’s rate","The EOB’s alternate code and the plan’s rule","Not a denial: post it; the difference is the patient’s"],
   ["Not a covered benefit / cosmetic","The plan excludes the service","The plan booklet and the eligibility response","Patient responsibility; appeal only with a medical reason"],
   ["Waiting period","The service came before the plan covers that class","The effective date and the class’s wait","Patient responsibility; appeal with proof of prior continuous coverage where the plan waives waits"],
   ["Records or narrative needed","The plan wants the X-ray, perio chart or narrative","What was sent, and what the plan asks for by procedure","Send the attachment with the claim number; note the date"],
   ["Tooth, surface, quadrant or duplicate","Wrong or missing tooth data, or the plan already paid it","The chart against the claim; the plan’s history","Corrected claim, or close as a duplicate"],
   ["Timely filing","Filed past the plan’s limit","The acceptance report and the plan’s limit","Proof of timely filing, or the client’s write-off rule; never the patient"],
   ["No prior authorization / out of network","Authorization missing on a plan that requires it; dentist not credentialed","The authorization number; the dentist’s network status on the DOS","Add the number on a corrected claim; or the practice’s out-of-network rule"]]},
  body:[
   "**Read the EOB, not just the code.** Dental EOBs explain in words: ‘benefit frequency exceeded’, ‘annual maximum has been met’, ‘tooth missing prior to coverage’, ‘alternate benefit applied’, ‘additional information required’. The remark decides the action; the CARC alone (often CO-119, CO-96, CO-197, CO-16) does not.",
   "**What we do when a claim denies.** Check the eligibility record and the plan’s rule for the DOS; correct the claim when the tooth, surface, code or date was wrong; send what the plan asked for; appeal with the records where the plan is wrong (a frequency counted from the wrong date, a tooth lost after the effective date, a medical reason for a non-covered service); and bill the patient only for what the plan’s rules and the practice’s rules make theirs. Every step goes in the note.",
   "**Prevent before you chase.** Eligibility before the visit with the frequencies, the maximum left, the waiting periods and the missing tooth clause; a predetermination for major work; the attachments on the first claim; the right tooth and surfaces. These stop most dental denials, and the claims that still deny usually point to the check that was missed."
  ],
  terms:[["Benefit frequency exceeded","The dental EOB’s wording for a frequency denial."],["Additional information required","The dental EOB’s wording for a records or narrative request; the claim is waiting, not denied."],["Alternate benefit applied","The plan paid the cheaper treatment’s rate; the difference is the patient’s."]],
  tips:["Four dates decide most dental denials: the last cleaning, the last bitewings or FMX, the prior crown or denture placement, and the extraction date of a missing tooth. Have them before you call.","A dental denial is often a patient balance, but only after the plan’s rule and the practice’s rule say so. Never move a balance to the patient because the plan said no."],
  remember:"Ten denials, one first check each. Frequency → last used? Maximum → left? Missing tooth → when lost? Alternate → not a denial. Covered? Waited? Records sent? Tooth right? Filed in time? Authorized and in network?",
  see:[["denial","CPT reached maximum allowance / frequency"],["denial","Maximum benefit exhausted"],["denial","Information requested from provider"],["denial","Duplicate claim"]],
  source:SRC},
 {id:"den-patient",title:"What the patient owes on a dental claim: the estimate, the difference and the write-off",
  keywords:["dental patient balance","what the patient owes dental","dental estimate","patient estimate dental","dental write off","ppo write off dental","dental overage","alternate benefit difference","bill the difference","balance billing dental","dental copay","dhmo copay","dental eob patient portion","dental credit balance","dental refund","in network dental fee schedule"],
  line:"On an in-network dental claim the patient owes their share of the contracted fee (deductible, coinsurance, anything over the maximum, anything the plan excludes) and the difference when the plan paid an alternate benefit; the gap between the dentist’s fee and the contracted fee is written off, never billed. Out of network, the plan pays its allowance and the balance is the patient’s.",
  body:[
   "**In network.** The dentist has agreed to the plan’s fee schedule. The plan pays its share of the contracted fee; the patient pays the deductible, their coinsurance (20% on basic, 50% on major), any amount over the annual maximum, any service inside a frequency limit or waiting period they were told about, and the **difference on an alternate benefit** (the plan allows the composite fee to be charged; it just pays at the amalgam rate). The difference between the dentist’s usual fee and the contracted fee is the **PPO write-off**: a contractual adjustment, never the patient’s.",
   "**Out of network.** The plan pays its percentage of its own allowance (often a usual and customary amount lower than the dentist’s fee). The patient owes the rest; balance billing is allowed because there is no contract. The patient’s share is larger and the estimate at the front desk matters more.",
   "**DHMO.** The patient pays the copay on the plan’s schedule for each procedure, to the assigned dentist. There is often no claim and no EOB, and no balance beyond the schedule.",
   "**Estimates and the EOB.** The front desk quotes the patient from the eligibility response: class, share, deductible left, maximum left, clauses. The EOB is the final word; when it differs, find why (the maximum went down, a frequency, an alternate benefit, a clause) before the statement goes out. A statement that bills the patient a plan write-off, or bills a frequency denial the patient was never warned about, is the fastest way to a complaint.",
   "**Credit balances.** Two plans paying as primary, a predetermination estimate collected in full and then the plan paying more than expected, a copay collected on a service that paid at 100%: all become patient refunds. Dental practices build credits easily because so much is collected at the visit; the posting check is that the patient’s payments plus the plan’s payments never exceed the allowed fee."
  ],
  compare:{title:"Who pays what",head:["Amount","In network","Out of network"],rows:[["Dentist’s fee above the plan’s contracted fee or allowance","PPO write-off (contractual adjustment)","Patient (balance billing)"],["Deductible, coinsurance","Patient","Patient"],["Over the annual maximum","Patient","Patient"],["Alternate benefit difference","Patient","Patient"],["Frequency limit, waiting period, exclusion","Patient, if told beforehand; else the practice’s rule","Patient"],["Timely filing, provider error","Write-off by the client’s rule, never the patient","Write-off by the client’s rule"]]},
  terms:[["PPO write-off","The gap between the dentist’s fee and the contracted fee on an in-network claim; a contractual adjustment."],["Alternate benefit difference","The gap between the fee for the treatment done and the plan’s payment at the cheaper treatment’s rate; billable to the patient."],["Usual and customary (dental)","The allowance an indemnity plan or an out-of-network claim is paid against."]],
  tips:["In network, the only amounts that reach the patient are the plan’s own: deductible, coinsurance, maximum, clauses and the alternate benefit difference. Everything else is a write-off.","Collect the estimate, post the EOB, then compare. If the patient paid more than the EOB leaves them, the difference is a refund, not a credit to hold."],
  remember:"In network: patient share of the contracted fee plus the alternate difference; the rest is written off. Out of network: the plan’s allowance, the balance to the patient. Collected more than owed: refund.",
  see:[["basics","cost-sharing"],["denial","Claim applied towards deductible"]],
  source:SRC},
 {id:"den-justify",title:"Justifying the dental claim: documentation, radiographs, narratives and compliance",
  keywords:["justify dental claim","dental documentation","dental compliance","dental fraud","upcoding dental","unbundling dental","dental audit","dental records request","dental narrative compliance","billing a cleaning as scaling","d4341 vs d1110","splitting quadrants","dental claim audit","right tooth right code","dental four rights"],
  line:"A dental claim stands up when the chart proves it: the tooth and surfaces match the note and the X-ray, the code matches what was done and nothing more, the attachments show why, and the dates are real. The classic dental compliance failures are upcoding a cleaning to scaling and root planing, adding surfaces, splitting one quadrant into two visits, and narratives written for the plan rather than from the chart.",
  body:[
   "**Right tooth, right surfaces, right code.** The claim must match the clinical note and the X-ray: the same tooth number, the same surfaces, the code for the work actually done. A two-surface filling billed as three, a filling billed as an onlay, a simple extraction billed as surgical: each is a false claim, and plans audit against the X-rays they hold.",
   "**The classic failures.** Billing a routine cleaning (D1110) as scaling and root planing (D4341) without the pocket depths to support it. Billing scaling on four quadrants when the chart supports one. Splitting one quadrant of scaling over two dates to get around a per-quadrant limit. Billing a build-up (D2950) on every crown by habit. Unbundling: billing the exam, the X-rays and the cleaning as separate visits when they were one, or billing a bitewing and a periapical set that equals an FMX as separate codes. Billing the date of the impression as the crown date when the plan pays on the seat date (plans differ: check which date the plan uses).",
   "**Narratives and attachments.** A narrative describes what the chart and X-ray show; it never adds findings that are not there. A records request is answered with the actual records. If the records do not support the code, the answer is a corrected claim, not a better narrative.",
   "**Compliance basics.** HIPAA on every call and note (two identifiers, minimum necessary); the plan’s billing guide and the CDT definitions; the practice’s own rules; and the client’s rule on what is written off and what is billed to the patient. Never choose a code because it pays, never bill the write-off, never bill both plans at once, never backdate.",
   "**The big picture.** A dental claim pays the first time when four things are right: the right **service** (what was done, each tooth its own line), the right **code** (CDT in force on the date, surfaces that match, ICD-10 where required), the right **paperwork** (eligibility, predetermination or authorization, X-rays, perio chart, narrative, missing teeth chart and prior placement date) and the right **payer order** (medical or accident coverage first where it applies, primary before secondary, the right plan for the patient’s Medicare or Medicaid). Get all four right and the plan has nothing to question."
  ],
  compare:{title:"The four rights",head:["Right","Means","If wrong"],rows:[["Right service","What was done, documented, one tooth per line","Upcoding, unbundling, split quadrants; audit risk"],["Right code","CDT in force on the DOS, surfaces that match, ICD-10 where required","Invalid code, surface mismatch, denial"],["Right paperwork","Eligibility, predetermination or authorization, X-rays, perio chart, narrative, missing teeth, prior placement date","Records request, missing tooth clause applied, frequency from the wrong date"],["Right payer order","Accident or medical first where it applies, primary before secondary","CO-22, primary EOB required, wrong payer"]]},
  terms:[["Upcoding (dental)","Billing a higher code than the work supports: a cleaning as scaling, two surfaces as three."],["Unbundling (dental)","Billing parts of one service separately: a full series as separate images."],["Seat date / prep date","The date a crown is cemented / the date the tooth is prepared; plans differ on which date they pay from."]],
  tips:["If the X-ray would not convince a reviewer, the code is wrong, not the narrative. Ask your supervisor before anything that looks chosen to make a claim pay.","Each dental plan says which date it pays a crown from, seat or prep. A claim dated before the plan’s date, or after the maximum reset, is a question before it is sent."],
  remember:"Right service + right code + right paperwork + right payer order = paid the first time. The chart and the X-ray decide the code; the narrative only describes them.",
  see:[["basics","hipaa"]],
  source:SRC}
]}
]});

/* Assessment questions: t = module short. Each wrong option carries its own "why not" (whyNot, in order). */
const Q=[
/* Dental basics */
{t:"Dental basics",q:"How many permanent teeth does an adult usually have, and how many of them are molars?",correct:"32 teeth, 12 of them molars (including the 4 wisdom teeth)",wrongs:["28 teeth, 8 of them molars","32 teeth, 8 of them premolars and no molars","20 teeth, lettered A to T"],whyNot:["28 is the count after the four wisdom teeth are removed; the full set is 32 with 12 molars.","There are 8 premolars and 12 molars; molars are the back grinding teeth.","20 lettered teeth are the primary (baby) teeth."],ex:"8 incisors, 4 canines, 8 premolars and 12 molars, including the 4 wisdom teeth, make 32."},
{t:"Dental basics",q:"Tooth number 1 in the Universal numbering system is:",correct:"The upper right wisdom tooth",wrongs:["The upper left wisdom tooth","The lower right wisdom tooth","The upper right front tooth"],whyNot:["The upper left wisdom tooth is 16.","The lower right wisdom tooth is 32.","The upper right front tooth is 8."],ex:"Counting starts at the upper right wisdom tooth (1), runs to the upper left (16), drops to the lower left (17) and ends at the lower right (32)."},
{t:"Dental basics",q:"Tooth 19 is in which quadrant?",correct:"Lower left (17–24)",wrongs:["Upper right (1–8)","Upper left (9–16)","Lower right (25–32)"],whyNot:["1 to 8 are upper right.","9 to 16 are upper left.","25 to 32 are lower right."],ex:"1–8 upper right, 9–16 upper left, 17–24 lower left, 25–32 lower right."},
{t:"Dental basics",q:"A claim for a child shows tooth ‘K’. That means:",correct:"A primary (baby) tooth, lower left quadrant",wrongs:["A permanent tooth with a typo","Tooth number 11","A supernumerary tooth"],whyNot:["Letters A to T are the baby teeth, not a typo.","Primary teeth use letters, not numbers; K is a lower left baby tooth.","Supernumerary (extra) teeth are numbered 51 to 82."],ex:"Baby teeth are lettered A to T: A–J across the top, K–T across the bottom."},
{t:"Dental basics",q:"Scaling and root planing on the upper right quadrant carries which area of oral cavity code?",correct:"10",wrongs:["20","01","00"],whyNot:["20 is the upper left quadrant.","01 is the whole upper arch.","00 is the entire mouth."],ex:"10 upper right, 20 upper left, 30 lower left, 40 lower right; 01 and 02 are the arches, 00 the whole mouth."},
{t:"Dental basics",q:"The same filling was done on teeth 19 and 30 on the same day. On the claim that is:",correct:"Two lines, one per tooth",wrongs:["One line with quantity 2","One line listing both tooth numbers","Two claims"],whyNot:["Each tooth is its own line; quantity is not used for teeth.","The tooth box holds one tooth per line.","One claim with two lines is correct; two claims are not needed."],ex:"One claim line per tooth, each with its own surfaces and code."},
{t:"Dental basics",q:"‘MOD’ in the surface box means the filling covers:",correct:"Three surfaces: mesial, occlusal and distal",wrongs:["One surface","Two surfaces","The whole tooth"],whyNot:["Three letters, three surfaces.","Three letters, three surfaces.","A whole-tooth restoration is a crown, which has no surface letters."],ex:"M mesial, O occlusal, D distal: a three-surface filling, coded D2160 (amalgam) or D2393 (composite, back tooth)."},
{t:"Dental basics",q:"A two-surface composite on a back tooth is coded:",correct:"D2392",wrongs:["D2391","D2150","D2331"],whyNot:["D2391 is one surface.","D2150 is a two-surface amalgam, not composite.","D2331 is a two-surface composite on a front tooth."],ex:"Back-tooth composites run D2391 (1), D2392 (2), D2393 (3), D2394 (4+)."},
{t:"Dental basics",q:"The surface on the tongue side of a tooth is:",correct:"Lingual (L)",wrongs:["Mesial (M)","Buccal (B)","Occlusal (O)"],whyNot:["Mesial is the side toward the midline.","Buccal is the cheek side.","Occlusal is the chewing surface."],ex:"M, D, O, I, F or B, L: the tongue side is lingual."},
{t:"Dental basics",q:"An onlay differs from an inlay because it:",correct:"Also covers one or more cusps of the tooth",wrongs:["Is a filling placed directly in the mouth","Covers the whole tooth","Replaces a missing tooth"],whyNot:["A direct filling is a restoration, not an inlay or onlay; both are lab-made pieces.","Covering the whole tooth is a crown.","Replacing a missing tooth is a bridge, implant or denture."],ex:"Filling → inlay → onlay → crown, from the smallest repair to the full cap. An onlay is more than an inlay and less than a crown."},
{t:"Dental basics",q:"A dental implant is:",correct:"An artificial root placed in the jaw to hold a replacement tooth or bridge",wrongs:["A tooth-coloured filling","A cap over a damaged tooth","A removable set of false teeth"],whyNot:["A tooth-coloured filling is a composite.","A cap over a tooth is a crown.","Removable false teeth are dentures."],ex:"The implant is the root; an abutment and a crown go on top once it heals."},
{t:"Dental basics",q:"Which X-ray shows the whole mouth, both jaws, on one image?",correct:"Panoramic (D0330)",wrongs:["Bitewing (D0274)","Periapical (D0220)","Full mouth series (D0210)"],whyNot:["Bitewings show the crowns of the back teeth and the bone between them.","A periapical shows one whole tooth.","A full mouth series is many small images, not one."],ex:"The panoramic is one wide image: erupted and emerging teeth, impacted wisdom teeth, the jaws."},
{t:"Dental basics",q:"A full mouth series (FMX) is typically covered:",correct:"Once every three to five years",wrongs:["Twice a year","Once a year","At every visit"],whyNot:["Twice a year is the cleaning frequency.","Once a year is the bitewing frequency.","No X-ray is covered at every visit."],ex:"Bitewings yearly; FMX and panoramic every three to five years, often sharing one limit."},
/* Dental codes */
{t:"Dental codes",q:"CDT codes are owned and updated by:",correct:"The American Dental Association, every 1 January",wrongs:["CMS, every 1 October","The AMA, every 1 January","Each dental plan, on its own schedule"],whyNot:["CMS runs HCPCS and ICD-10, and 1 October is the ICD-10 date.","The AMA owns CPT, not CDT.","Plans adopt CDT; they do not write it."],ex:"CDT is the ADA’s code set, updated each January; the code in force on the date of service is the one the plan accepts."},
{t:"Dental codes",q:"A code starting D4 belongs to which family?",correct:"Periodontics (gum treatment)",wrongs:["Restorative (fillings and crowns)","Endodontics (root canals)","Oral surgery (extractions)"],whyNot:["Restorative is D2.","Endodontics is D3.","Oral surgery is D7."],ex:"D0 diagnostic, D1 preventive, D2 restorative, D3 root canals, D4 gums, D5 dentures, D6 implants and bridges, D7 surgery, D8 braces, D9 the rest."},
{t:"Dental codes",q:"D1110 is:",correct:"An adult cleaning (prophylaxis)",wrongs:["A child cleaning","A periodic exam","Scaling and root planing"],whyNot:["The child cleaning is D1120.","The periodic exam is D0120.","Scaling and root planing is D4341 or D4342."],ex:"D1110 adult cleaning, D1120 child cleaning: preventive, usually paid at 100%."},
{t:"Dental codes",q:"D4341 is scaling and root planing for:",correct:"Four or more teeth in a quadrant",wrongs:["One to three teeth in a quadrant","The whole mouth","A single tooth"],whyNot:["One to three teeth is D4342.","It is billed per quadrant, not per mouth.","Scaling is a quadrant service; a single tooth falls under D4342."],ex:"D4341 four or more teeth per quadrant, D4342 one to three; the area of oral cavity code names the quadrant."},
{t:"Dental codes",q:"A root canal on a molar is coded:",correct:"D3330",wrongs:["D3310","D2740","D7140"],whyNot:["D3310 is a root canal on a front tooth.","D2740 is a porcelain crown.","D7140 is a simple extraction."],ex:"D3310 front tooth, D3320 premolar, D3330 molar."},
{t:"Dental codes",q:"Which code is a surgical removal of a fully impacted wisdom tooth?",correct:"D7240",wrongs:["D7140","D7210","D9110"],whyNot:["D7140 is a simple extraction of an erupted tooth.","D7210 is a surgical extraction of an erupted tooth.","D9110 is emergency treatment of pain."],ex:"D7140 simple, D7210 surgical, D7220 to D7240 impacted (soft tissue to fully bony)."},
{t:"Dental codes",q:"Dental work is being billed to a medical plan. The codes on that claim are:",correct:"CPT or HCPCS with ICD-10 diagnoses, on a CMS-1500",wrongs:["CDT codes on a CMS-1500","CDT codes on the ADA form","CPT codes on the ADA form"],whyNot:["Medical plans do not process CDT codes.","The ADA form goes to dental plans.","Medical plans take the CMS-1500 or 837P."],ex:"Cross-coding: the dental service is translated to CPT or HCPCS and ICD-10 for the medical plan."},
{t:"Dental codes",q:"Which ICD-10 code family is dental caries (decay)?",correct:"K02.-",wrongs:["K05.-","Z01.20","S02.5-"],whyNot:["K05 is gingivitis and periodontitis.","Z01.20 is a dental exam without abnormal findings.","S02.5- is a broken tooth from an injury."],ex:"Chapter K00–K14 covers the mouth: K02 decay, K04 pulp and abscess, K05 gums, K08 loss of teeth."},
{t:"Dental codes",q:"On the ADA claim form, the missing teeth chart is used by the plan to:",correct:"Apply the missing tooth clause and check bridges, partials and implants",wrongs:["Count how many cleanings are due","Price the X-rays","Decide the place of service"],whyNot:["Cleanings follow frequency limits, not the missing teeth chart.","X-rays are priced by their codes.","Place of service is its own box."],ex:"The chart marks every lost tooth; the plan compares it with the extraction dates and the policy effective date."},
{t:"Dental codes",q:"Items 43 and 44 on the ADA form (replacement of a prosthesis and the date of prior placement) matter because:",correct:"The plan applies its replacement limit (five to ten years) from that date",wrongs:["They set the patient’s copay","They prove the dentist is in network","They are needed for every filling"],whyNot:["Copays come from the plan’s schedule, not these boxes.","Network status is checked against the treating dentist’s NPI.","They apply to crowns, bridges and dentures, not fillings."],ex:"A blank prior placement date on a replacement crown is a records request waiting to happen."},
{t:"Dental codes",q:"A crown claim is held for ‘additional information required’. The claim is:",correct:"Waiting for the X-ray or narrative; send it with the claim number and note the date",wrongs:["Denied; appeal it","Paid; close it","The patient’s to pay"],whyNot:["It is a records request, not a denial.","Nothing has been paid.","The patient is not responsible for a records request."],ex:"Send what the plan asks for, the way it asks, and note the date; unanswered requests become denials."},
{t:"Dental codes",q:"A predetermination from a dental plan is:",correct:"The plan’s estimate before treatment, not a guarantee of payment",wrongs:["A guarantee the plan will pay that amount","The same as a Medicaid prior authorization","Required before every cleaning"],whyNot:["Payment still depends on eligibility and the maximum left on the date of service.","A prior authorization is an approval that some plans require; a predetermination is an estimate.","Predeterminations are for major work, not routine care."],ex:"Item 1 marks the claim as a request for predetermination; keep the letter on the account to explain any difference later."},
{t:"Dental codes",q:"Which attachment does a plan usually want for scaling and root planing?",correct:"The periodontal chart with pocket depths, plus X-rays showing bone loss",wrongs:["A photo of the cleaning","The missing teeth chart","The prior crown date"],whyNot:["A photo does not show pocket depths.","The missing teeth chart is for bridges, partials and implants.","The prior placement date is for replacement crowns and dentures."],ex:"Crown → X-ray and narrative. Root canal → periapical. Scaling → perio chart. Surgery → X-ray and narrative."},
/* Dental plans */
{t:"Dental plans",q:"A typical dental PPO pays preventive, basic and major services at about:",correct:"100%, 80% and 50%",wrongs:["50%, 80% and 100%","80% for everything","100% for everything up to the maximum"],whyNot:["That is reversed: preventive is paid best.","Shares differ by class.","Only preventive is usually 100%."],ex:"Preventive 100, basic 80, major 50, after the deductible, up to the annual maximum."},
{t:"Dental plans",q:"The annual maximum on a dental plan is:",correct:"The most the plan pays per member in a benefit year, typically $1,000 to $2,000",wrongs:["The most the patient pays in a year","The dentist’s highest fee","A limit on the number of visits"],whyNot:["Dental plans cap what the plan pays; the patient has no out-of-pocket limit.","Fees are set by the fee schedule, not the maximum.","Visits are limited by frequency rules, not the maximum."],ex:"Above the maximum, everything is the patient’s. One crown can use most of it."},
{t:"Dental plans",q:"A patient enrolled four months ago wants a crown on a plan with a 12-month waiting period for major services. The crown is:",correct:"Not covered yet: the patient pays",wrongs:["Covered at 50%","Covered at 100%","Covered if a predetermination is sent"],whyNot:["Major services are not covered until the wait is over.","Nothing on a dental plan is 100% except preventive care.","A predetermination would only confirm the waiting period."],ex:"Waiting periods: none for preventive, 3 to 6 months for basic, 6 to 12 months for major, unless the plan waives them for prior coverage."},
{t:"Dental plans",q:"Original Medicare covers:",correct:"Dental care tied to a covered medical treatment, such as an exam before a transplant or heart valve surgery",wrongs:["Routine cleanings twice a year","Dentures","Implants"],whyNot:["Medicare does not cover routine cleanings.","Medicare does not cover dentures.","Medicare does not cover implants."],ex:"Routine dental comes from a Medicare Advantage dental benefit or a stand-alone dental plan, not from Medicare."},
{t:"Dental plans",q:"Children’s dental care under Medicaid is:",correct:"Required: EPSDT covers it in every state",wrongs:["Optional, state by state","Not covered","Covered only for emergencies"],whyNot:["Adult dental is the state-by-state benefit; children’s dental is mandatory.","Children’s dental care is covered.","Emergency-only is a common adult limit, not the children’s benefit."],ex:"EPSDT (Early and Periodic Screening, Diagnostic and Treatment) covers children’s dental care under 21; CHIP covers children too."},
{t:"Dental plans",q:"In a DHMO, the patient:",correct:"Sees an assigned dentist and pays a fixed copay from the plan’s schedule; often no claim is sent",wrongs:["Can see any dentist and pays 50%","Pays the dentist’s full fee and claims it back","Pays nothing for any service"],whyNot:["A DHMO has an assigned dentist and a copay schedule, not a percentage.","Claiming money back is an indemnity or out-of-network pattern.","Copays apply per procedure."],ex:"The DHMO pays the dentist a monthly capitation; the patient pays scheduled copays."},
{t:"Dental plans",q:"Bitewing X-rays were taken 8 months after the last set on a plan that covers them once a year. They:",correct:"Deny as frequency; the patient pays only if they were told beforehand",wrongs:["Pay at 50%","Pay in full","Count against next year’s limit"],whyNot:["Plans do not half-pay a frequency denial.","Inside the window the service is not covered.","Frequency limits do not borrow from the next period."],ex:"The last-used date decides. Record it at eligibility and warn the patient before the service."},
{t:"Dental plans",q:"A composite filling on a back tooth is paid at the amalgam rate. This is:",correct:"The alternate benefit: not a denial; the difference is the patient’s",wrongs:["A denial to appeal","A duplicate","A coding error by the dentist"],whyNot:["The plan paid something; it applied the cheaper treatment’s rate by its rules.","Nothing was billed twice.","The composite code was right; the plan chose to pay the alternate."],ex:"Least expensive alternative treatment: the plan pays the cheaper option that would also work, and the patient pays the difference."},
{t:"Dental plans",q:"A bridge is denied under the missing tooth clause. That means:",correct:"The tooth being replaced was lost before the patient’s coverage began",wrongs:["The bridge was billed with the wrong tooth number","The plan does not cover bridges","The patient had too many cleanings"],whyNot:["A wrong tooth number is a claim error, not the missing tooth clause.","The plan covers bridges; it excludes replacing a tooth lost before the policy started.","Cleanings have nothing to do with the clause."],ex:"Check the extraction date against the effective date; if the tooth was lost after coverage began, appeal."},
{t:"Dental plans",q:"A child is covered by both parents’ dental plans. Which plan is primary?",correct:"The plan of the parent whose birthday comes first in the calendar year",wrongs:["The father’s plan","The plan with the higher maximum","Both pay half"],whyNot:["Gender does not decide; the birthday rule does.","The maximum plays no part in the order.","Plans pay in order, primary then secondary."],ex:"The birthday rule: month and day only, unless a court decree says otherwise."},
{t:"Dental plans",q:"Impacted wisdom teeth with a documented medical reason are billed:",correct:"To the medical plan first, cross-coded with CPT and ICD-10, then to the dental plan with the EOB",wrongs:["To the dental plan only","To both plans at once","To the patient"],whyNot:["Oral surgery with a medical reason is medical first.","Never two plans at once; primary first, then the secondary with the EOB.","Covered care is billed to insurance before the patient."],ex:"Injuries, oral surgery, TMJ, sleep appliances and medically linked dental care go to the medical plan first."},
{t:"Dental plans",q:"A sleep apnea oral appliance (HCPCS E0486) is a claim for:",correct:"The medical plan, with the sleep study and the physician’s prescription",wrongs:["The dental plan","Medicare Part D","The patient only"],whyNot:["Dental plans generally do not cover sleep apnea appliances.","Part D covers drugs, not appliances.","It is covered medical equipment when the medical plan’s rules are met."],ex:"E0486 is a HCPCS code on a medical claim; the dentist makes the appliance, the physician treating the apnea prescribes it."},
/* Dental denials */
{t:"Dental denials",q:"A dental EOB says ‘benefit frequency exceeded’ on a cleaning. The first check:",correct:"The last cleaning date on the eligibility response against the plan’s frequency",wrongs:["The tooth number","The patient’s deductible","The dentist’s NPI"],whyNot:["Cleanings are per mouth, not per tooth.","The deductible does not cause a frequency denial.","The NPI matters for provider denials, not frequency."],ex:"Frequency denials are decided by dates: have the last-used dates before you call."},
{t:"Dental denials",q:"A crown paid only $300 of $900 and the EOB says ‘annual maximum has been met’. The balance is:",correct:"The patient’s, beyond the plan’s maximum",wrongs:["A plan error to appeal","A PPO write-off","The secondary dental plan’s, automatically"],whyNot:["The plan paid up to its cap; that is the rule, not an error.","The write-off is the gap between the fee and the contracted fee, not the maximum.","A secondary pays only if there is one and it is billed with the EOB, and its own maximum applies."],ex:"Above the annual maximum, everything is the patient’s. The maximum left on the date of service decides how much of a major claim pays."},
{t:"Dental denials",q:"An implant is denied under the missing tooth clause, but the chart shows the tooth was extracted three months after the policy began. You:",correct:"Appeal with the extraction record: the clause applies only to teeth lost before coverage began",wrongs:["Bill the patient","Write it off","Resubmit the same claim"],whyNot:["The clause does not apply, so the plan should pay; the patient is not responsible yet.","There is money to recover.","The same claim will deny the same way; the plan needs the proof."],ex:"The missing tooth clause turns on one date: when the tooth was lost. Prove it."},
{t:"Dental denials",q:"A claim for teeth whitening is denied as not covered. You:",correct:"Bill the patient by the practice’s rule: cosmetic work is excluded",wrongs:["Appeal with a narrative","Rebill it as a cleaning","Send it to the medical plan"],whyNot:["No narrative makes a cosmetic service covered.","Rebilling one service as another is fraud.","Medical plans do not cover cosmetic dental work."],ex:"Whitening and veneers for looks alone are excluded on almost every plan."},
{t:"Dental denials",q:"A claim is denied ‘additional information required’ 40 days ago and nothing was sent. The next step:",correct:"Send the records the plan asked for with the claim number now; unanswered requests become denials",wrongs:["Wait for the plan to pay","Bill the patient","Close the claim"],whyNot:["The plan is waiting for the records; it will not pay without them.","A records request is not patient responsibility.","Closing abandons a payable claim."],ex:"A records request is a waiting claim, not a denial; it is only lost if nobody answers."},
{t:"Dental denials",q:"The plan paid a filling on tooth 30 last month. The same filling, same surfaces, same tooth, is billed again today. Expect:",correct:"A duplicate denial; check the chart before anything else",wrongs:["Payment at 80%","An alternate benefit","A frequency denial on the cleaning"],whyNot:["The plan already paid it.","The alternate benefit changes the rate; it does not pay a duplicate.","Cleanings are not involved."],ex:"Same tooth, same surfaces, same code: a duplicate unless the chart shows a replacement, and plans limit replacements too."},
{t:"Dental denials",q:"A dental claim is past the plan’s filing limit and the clearinghouse shows it was accepted in time. You:",correct:"Resubmit with the acceptance report as proof of timely filing",wrongs:["Bill the patient","Write it off","Change the date of service"],whyNot:["Timely filing is never the patient’s to pay.","There is proof it was filed in time.","Changing a date of service is fraud."],ex:"The acceptance report proves the original filing date. Without proof, the client’s write-off rule applies."},
{t:"Dental denials",q:"A Medicaid dental claim is denied for no prior authorization. First:",correct:"Check the authorization record for the DOS and send a corrected claim with the number",wrongs:["Bill the patient","Appeal with a narrative","Send it to the medical plan"],whyNot:["Medicaid members are not billed for a missing authorization.","A narrative does not replace the authorization number.","It is a dental service under Medicaid; the dental program decides."],ex:"Medicaid programs and some plans require authorization before certain services; the number goes on the claim."},
{t:"Dental denials",q:"In network, the gap between the dentist’s $200 fee and the $140 contracted fee is:",correct:"A PPO write-off, never billed to the patient",wrongs:["The patient’s","The secondary plan’s","An alternate benefit difference"],whyNot:["The dentist agreed to the contracted fee; the gap is a contractual adjustment.","Secondary plans consider the patient’s share, not the write-off.","The alternate benefit difference is between two treatments’ fees, not the fee and the contract."],ex:"In network, the patient owes only the plan’s own amounts: deductible, coinsurance, maximum, clauses, the alternate difference."},
{t:"Dental denials",q:"The patient paid a $450 estimate at the visit; the EOB leaves the patient $300. The $150 is:",correct:"A refund to the patient",wrongs:["A credit to hold for next time","The practice’s to keep","The plan’s"],whyNot:["Money the patient does not owe is refunded, not held.","The practice may keep only what the EOB leaves the patient.","The plan has paid its share; the excess came from the patient."],ex:"Patient payments plus plan payments never exceed the allowed fee; the excess is a refund."},
{t:"Dental denials",q:"A routine cleaning (D1110) is billed as scaling and root planing (D4341) with no pocket depths in the chart. This is:",correct:"Upcoding, a false claim: the chart does not support the code",wrongs:["An alternate benefit","A frequency issue","Allowed if the plan pays it"],whyNot:["The alternate benefit is the plan paying a cheaper treatment, not the practice billing a dearer one.","Frequency is about dates; this is about the code.","A plan paying a false claim does not make it right; it makes it an audit finding."],ex:"The code matches what was done and documented. Scaling needs the perio chart."},
{t:"Dental denials",q:"Which four things make a dental claim pay the first time?",correct:"Right service, right code, right paperwork, right payer order",wrongs:["Right dentist, right price, right day, right chair","Right tooth, right crown, right cement, right lab","Right CDT, right fee, right NPI, right stamp"],whyNot:["Those are not the four rights.","Those are clinical and lab choices, not the claim’s four rights.","Codes and identifiers are part of ‘right code’; paperwork and payer order are missing."],ex:"Right service + right code + right paperwork + right payer order = paid the first time."}
];
Q.forEach(x=>{ x.c="dental"; SPEC_QUIZ.push(x); });
})();
